<script setup lang="ts">
import {ref} from 'vue';import {usePhase1} from '@/pinia/phase1';import {stateNames} from './catalog';import type {P1State} from '@/views/AgentWork/interface';
const props=defineProps<{id:string;state?:P1State}>();const emit=defineEmits<{close:[]}>();const s=usePhase1();const reason=ref('');const conclusion=ref('');const state=ref<P1State>(props.state||'pending');const error=ref('');
function save(){if(!reason.value.trim()){error.value='请填写纠正原因';return;}error.value=props.state?s.progress(props.id,state.value,reason.value):s.correctResult(props.id,conclusion.value,reason.value);if(!error.value)emit('close');}
</script>
<template><div class="p1-overlay"><section class="p1-dialog" role="dialog" aria-modal="true" aria-label="纠正结果"><header><h2>{{props.state?'运输状态纠正':'事件结果纠正'}}</h2><button @click="emit('close')">取消</button></header><p>{{id}}</p><label v-if="props.state">正确状态<select v-model="state"><option v-for="(name,key) in stateNames" :key="key" :value="key">{{name}}</option></select></label><label v-else>纠正结论<input v-model="conclusion" placeholder="例如：合理停车，取消异常"/></label><label>纠正原因<textarea v-model="reason" rows="3" placeholder="填写依据，保留到纠正记录中"/></label><p class="p1-muted">原始事实和历史结果保留。结果纠正取消关联异常及后续提醒；运输状态需单独纠正，已结束监听不会自动重启。</p><p class="p1-error" role="status">{{error}}</p><button class="primary" @click="save">保存纠正</button></section></div></template>
